// try/catch que nunca tumba el flujo. Si el modelo devolvio algo que no es
// JSON, se responde con una espera segura y se marca para escalar a humano.
const crudo = $json.choices?.[0]?.message?.content
let salida
try {
  salida = JSON.parse(crudo)
} catch (error) {
  salida = {
    mensaje: 'Permitame un momento, por favor. Le confirmo enseguida.',
    requiere_escalar_humano: true,
    error_parseo: String(error),
  }
}
const base = $('Extraer mensaje y referral').item.json
return [{ json: { telefono: base.telefono, dedupe_key: base.dedupe_key, salida, datos_crm: $json.data || null } }]

const pedido = $json.datos_crm || {}

// No existe API de despacho de courier en Ecuador: el despacho es
// humano-confirmado. Esto solo ARMA la solicitud; el operador la ejecuta en
// la app de Uber o con la mensajeria local.
//
// Solo se prepara si la lavanderia gestiona ese tramo por app Y ya esta
// pagado. Nunca se despacha un tramo app sin su pago confirmado.
const listo = pedido.metodo_transporte_recoleccion === 'app' && pedido.pago_recoleccion === 'pagado'
if (!listo) return []

return [{ json: { solicitud_despacho: {
  requiere_accion_humana: true,
  pedido_id: pedido.pedido_id,
  vehiculo: pedido.vehiculo_sugerido,
  direccion: pedido.direccion_recoleccion,
  ventana: pedido.ventana_recoleccion_inicio,
} } }]
